import java.util.*;

public class Solution {
  public static int solve(int[] greed, int[] sizes) {
    int[] g = greed.clone(), s = sizes.clone();
    Arrays.sort(g);
    Arrays.sort(s);
    int i = 0;
    for (int x : s) if (i < g.length && x >= g[i]) i++;
    return i;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {1, 2, 3}, new int[] {1, 1}));
  }
}

Lemonade Change.source:
import java.util.*;

public class Solution {
  public static boolean solve(int[] bills) {
    int five = 0, ten = 0;
    for (int b : bills) {
      if (b == 5) five++;
      else if (b == 10) {
        if (five == 0) return false;
        five--;
        ten++;
      } else if (b == 20) {
        if (ten > 0 && five > 0) {
          ten--;
          five--;
        } else if (five >= 3) five -= 3;
        else return false;
      } else throw new IllegalArgumentException();
    }
    return true;
  }

  public static void main(String[] args) {
    System.out.println(solve(new int[] {5, 5, 5, 10, 20}));
  }
}

